console.log(y);
let y = 5;

What does this code log?

const make = () => { a: 1 };
console.log(make());

What does this code log?

const { a = 10, b = 20 } = { a: 1, b: undefined };
console.log(a, b);

What does this code log?

const a = [1, 2];
const b = [...a, 3];
a.push(9);
console.log(b);

What does this code log?

const user = {};
console.log(user.profile?.name);

What does this code log?

const a = { x: 1 };
const b = a;
b.x = 2;
console.log(a.x);

In what order are the numbers logged?

console.log(1);
setTimeout(() => console.log(2), 0);
console.log(3);

In what order are the letters logged?

console.log("A");
setTimeout(() => console.log("B"), 0);
Promise.resolve().then(() => console.log("C"));
console.log("D");

In what order are the numbers logged?

async function f() {
  console.log(1);
  await null;
  console.log(2);
}
f();
console.log(3);

What does this code log?

for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0);
}

What does this code log?

function counter() {
  let c = 0;
  return () => ++c;
}
const a = counter();
const b = counter();
a();
a();
console.log(a(), b());

In strict mode (for example inside an ES module), what happens here?

const obj = {
  name: "obj",
  greet() { return this.name; }
};
const g = obj.greet;
console.log(g());

What does this code log?

function Person(name) { this.name = name; }
Person.prototype.hi = function () { return "hi"; };
const p = new Person("Al");
console.log(p.hasOwnProperty("hi"), "hi" in p);

What happens with this code?

class A {
  #x = 1;
}
const a = new A();
console.log(a.#x);

Clicking the child element produces which log order?

parent.addEventListener("click", () => console.log("parent"), true);
child.addEventListener("click", () => console.log("child"));

What happens when this code runs?

foo();
bar();
function foo() { console.log("foo"); }
var bar = function () { console.log("bar"); };

