const a = { x: { y: 1 } };
const b = { ...a };
b.x.y = 2;
console.log(a.x.y);

count starts at 0. What is count after one click?

const [count, setCount] = useState(0);
function handleClick() {
  setCount(count + 1);
  setCount(count + 1);
  setCount(count + 1);
}

count starts at 0. What is count after one click?

const [count, setCount] = useState(0);
function handleClick() {
  setCount(c => c + 1);
  setCount(c => c + 1);
  setCount(c => c + 1);
}

What happens with this input?

const [name, setName] = useState("");
return <input value={name} />;

What is the problem with this update?

const [items, setItems] = useState([]);
function add(x) {
  items.push(x);
  setItems(items);
}

In React 18+, how many re-renders does this cause?

setTimeout(() => {
  setA(1);
  setB(2);
}, 1000);

Child is wrapped in React.memo. Why does it still re-render whenever Parent re-renders?

function Parent() {
  const [n, setN] = useState(0);
  return <Child onSelect={() => console.log("hi")} />;
}

What does the displayed count do over time?

const [count, setCount] = useState(0);
useEffect(() => {
  const id = setInterval(() => setCount(count + 1), 1000);
  return () => clearInterval(id);
}, []);

What is user.age after this update re-renders?

const [user, setUser] = useState({ name: "Al", age: 30 });
// later:
setUser({ name: "Bo" });

